import json,csv,re

def load_md(path):
    out={}
    for line in open(path, encoding='utf-8'):
        m = re.match(r'- \*\*(oauth-s04-t04-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \|', line)
        if m:
            out[m.group(1)] = (m.group(2), m.group(3))
    return out

def load_jsonl(path):
    out={}
    for line in open(path, encoding='utf-8'):
        line=line.strip()
        if not line: continue
        d=json.loads(line)
        out[d['case']] = (d['system'], d['status'])
    return out

def load_csv(path):
    out={}
    with open(path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            out[row['case']] = (row['system'], row['status'])
    return out

def load_yaml(path):
    out={}
    case=system=status=None
    for line in open(path, encoding='utf-8'):
        line=line.strip()
        if line.startswith('- case:'):
            case=line.split(':',1)[1].strip()
        elif line.startswith('system:'):
            system=line.split(':',1)[1].strip()
        elif line.startswith('status:'):
            status=line.split(':',1)[1].strip()
            out[case]=(system,status)
    return out

def load_log(path):
    out={}
    for line in open(path, encoding='utf-8'):
        m = re.match(r'case=(\S+) system=(\S+) status=(\S+)', line)
        if m:
            out[m.group(1)]=(m.group(2), m.group(3))
    return out

md=load_md('oauth-s04-t04-evidence-01.md')
jl=load_jsonl('oauth-s04-t04-evidence-02.jsonl')
cs=load_csv('oauth-s04-t04-evidence-03.csv')
ym=load_yaml('oauth-s04-t04-evidence-04.yaml')
lg=load_log('oauth-s04-t04-evidence-05.log')

common = set(md) & set(jl) & set(cs) & set(ym) & set(lg)
print('common count', len(common))
mismatches=[c for c in common if not (md[c]==jl[c]==cs[c]==ym[c]==lg[c])]
print('mismatches on (system,status) across all five for common ids:', len(mismatches))
print(sorted(md)[0], sorted(md)[-1])
print(sorted(jl)[0], sorted(jl)[-1])
print(sorted(cs)[0], sorted(cs)[-1])
print(sorted(ym)[0], sorted(ym)[-1])
print(sorted(lg)[0], sorted(lg)[-1])
