cd "maintenance/inputs/oauth-s04/redemption-compatibility" && PY=/c/Users/Billy/Documents/GitHub/long-context-monitoring-project/.venv/Scripts/python
"$PY" -c "
import re, csv, json

def parse_md(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.search(r'\*\*(oauth-s04-t08-\d{6})\*\* \| System: ([\w-]+) \| Status: ([\w-]+)', line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

def parse_jsonl(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line:
                d = json.loads(line)
                out[d['case']] = (d['system'], d['status'])
    return out

def parse_csv(path):
    out = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            out[row['case']] = (row['system'], row['status'])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = None
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line.startswith('- case:'):
                case = line.split(':',1)[1].strip()
            elif line.startswith('system:'):
                system = line.split(':',1)[1].strip()
            elif line.startswith('status:'):
                status = line.split(':',1)[1].strip()
                out[case] = (system, status)
    return out

def parse_log(path):
    out = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.search(r'case=(\S+) system=(\S+) status=(\S+)', line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

files = {
    'md': parse_md('oauth-s04-t08-evidence-01.md'),
    'jsonl': parse_jsonl('oauth-s04-t08-evidence-02.jsonl'),
    'csv': parse_csv('oauth-s04-t08-evidence-03.csv'),
    'yaml': parse_yaml('oauth-s04-t08-evidence-04.yaml'),
    'log': parse_log('oauth-s04-t08-evidence-05.log'),
}

for name, d in files.items():
    cases = list(d.keys())
    dupes = len(cases) - len(set(cases))
    systems = sorted(set(v[0] for v in d.values()))
    statuses = sorted(set(v[1] for v in d.values()))
    print(name, 'count=', len(cases), 'dupes=', dupes, 'min=', min(cases), 'max=', max(cases), 'systems=', systems, 'statuses=', statuses)

common = set(files['md']) & set(files['jsonl']) & set(files['csv']) & set(files['yaml']) & set(files['log'])
print('common count=', len(common))
mismatches = 0
for c in common:
    vals = set(files[name][c] for name in files)
    if len(vals) != 1:
        mismatches += 1
        print('MISMATCH', c, vals)
print('mismatches=', mismatches)
"

