cd "maintenance/inputs/oauth-s04/stale-code-cleanup" && python -c "
import re, json, csv

def parse_md(f):
    d={}
    for line in open(f):
        m=re.search(r'oauth-s04-t11-(\d{6}).*?System:\s*([a-z0-9_-]+).*?Status:\s*([a-z-]+)', line)
        if m:
            d['oauth-s04-t11-'+m.group(1)]=(m.group(2), m.group(3))
    return d

def parse_jsonl(f):
    d={}
    for line in open(f):
        line=line.strip()
        if not line: continue
        o=json.loads(line)
        d[o['case']]=(o['system'], o['status'])
    return d

def parse_csv(f):
    d={}
    with open(f, newline='') as fh:
        for r in csv.DictReader(fh):
            d[r['case']]=(r['system'], r['status'])
    return d

def parse_yaml(f):
    d={}
    text=open(f).read()
    blocks=re.findall(r'case:\s*(oauth-s04-t11-\d{6})\s*\n\s*system:\s*(\S+)\s*\n\s*status:\s*(\S+)', text)
    for c,s,st in blocks:
        d[c]=(s,st)
    return d

def parse_log(f):
    d={}
    for line in open(f):
        m=re.search(r'case=(oauth-s04-t11-\d{6}) system=(\S+) status=(\S+)', line)
        if m:
            d[m.group(1)]=(m.group(2), m.group(3))
    return d

md=parse_md('oauth-s04-t11-evidence-01.md')
jsonl=parse_jsonl('oauth-s04-t11-evidence-02.jsonl')
csvd=parse_csv('oauth-s04-t11-evidence-03.csv')
yaml=parse_yaml('oauth-s04-t11-evidence-04.yaml')
log=parse_log('oauth-s04-t11-evidence-05.log')

print('parsed counts:', len(md), len(jsonl), len(csvd), len(yaml), len(log))

common = set(md) & set(jsonl) & set(csvd) & set(yaml) & set(log)
print('common ids:', len(common))

mismatches=[]
for c in sorted(common):
    vals = {md[c], jsonl[c], csvd[c], yaml[c], log[c]}
    if len(vals) != 1:
        mismatches.append((c, md[c], jsonl[c], csvd[c], yaml[c], log[c]))
print('mismatches:', len(mismatches))
for m in mismatches[:10]:
    print(m)
